export function findKeyword(name: string): KeywordInfo | undefined {
  const key = name.toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '');
  return KEYWORD_DATA[key];
}

export function findKeywordsByCategory(category: KeywordCategory): KeywordInfo[] {
  return Object.values(KEYWORD_DATA).filter(k => k.category === category);
}

